'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { validateProduct, vendorCatalogService, type ProductInput, type VendorProduct } from '@/lib/vendor/catalog'
import { CatalogFeedback } from '../../../components/CatalogFeedback'
import { ProductForm } from '../../../components/ProductForm'

export default function EditProductPage({ params }: { params: Promise<{ id: string }> }) { const [vendorId, setVendorId] = useState<string | null>(null); const [product, setProduct] = useState<VendorProduct | null>(null); const [error, setError] = useState(''); useEffect(() => { void Promise.all([params, createClient().auth.getUser()]).then(async ([route, { data: { user } }]) => { if (!user || (getUserRole(user) !== 'vendor' && getUserRole(user) !== 'admin')) return; setVendorId(user.id); setProduct(await vendorCatalogService.get(user.id, route.id)) }) }, [params]); async function save(input: ProductInput) { const errors = validateProduct(input); if (Object.keys(errors).length) { setError(Object.values(errors)[0]); return } if (!vendorId || !product) return; const currentVendorId = vendorId; await vendorCatalogService.update(currentVendorId, product.id, input); if (product.status === 'rejected' || product.status === 'vendor_fix_required') await vendorCatalogService.resubmit(currentVendorId, product.id); window.location.href = `/vendor/products/${product.id}` } if (!product) return <main className="vendor-page"><div className="product-editor-shell"><CatalogFeedback type={vendorId ? 'loading' : 'error'}>{vendorId ? 'Loading product...' : 'This product could not be found.'}</CatalogFeedback></div></main>; const locked = product.status === 'submitted' || product.status === 'under_review' || product.status === 'resubmitted'; return <main className="vendor-page"><header className="vendor-header"><Link href={`/vendor/products/${product.id}`} className="logo logo-active">Furnish<span>AI</span></Link><span className="vendor-header-label">Edit product</span></header><div className="product-editor-shell"><div className="product-editor-heading"><p className="vendor-eyebrow">Catalog / Edit product</p><h1>{locked ? 'Product is under review' : 'Refine this listing'}</h1><p>{locked ? 'This product is locked until the marketplace review team completes its review.' : product.status === 'rejected' || product.status === 'vendor_fix_required' ? 'Correct the requested changes and save to resubmit this product.' : 'Changes to approved products return to submission review so approval is never bypassed.'}</p></div>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}<ProductForm initialValue={{ name: product.name, sku: product.sku, category: product.category, description: product.description, price: product.price, stock: product.stock, images: product.images, variants: product.variants }} submitLabel={product.status === 'rejected' || product.status === 'vendor_fix_required' ? 'Save changes and resubmit' : 'Save changes'} onSubmit={save} locked={locked} /></div></main> }